                    category_name: row.category_name,
                    registered_at: row
                        .registration_date
                        .map(|date| {
                            chrono::DateTime::from_timestamp(
                                date.unix_timestamp(),
                                date.nanosecond(),
                            )
                            .ok_or_else(|| {
                                EntityDetailsRepoError::DatabaseError(
                                    "Stored registration date is out of range".into(),
                                )
                            })
                        })
                        .transpose()?,
                    entries: Vec::new(),
                });
            }
            if row.entry_id.is_some() {
                let funder = row
                    .funder_id
                    .zip(row.funder_name)
                    .map(|(id, name)| FunderReference {
                        id: FunderId::new(id),
                        name,
                    });
                if let Some(declaration) = declarations.last_mut() {
                    declaration.entries.push(DeclaredFunding {
                        funder,
                        amount: row.amount,
                        currency: row.currency,
                        payment_type: row.payment_type,
                    });
                }
            }
        }
        tx.commit().await?;
        Ok(Some(MemberHistory {
            member,
            declarations,
        }))
    }

    async fn funder_funding(
        &self,
        id: FunderId,
    ) -> Result<Option<FunderFunding>, EntityDetailsRepoError> {
        let mut tx = self.pool().begin().await?;
        sqlx::query!("SET TRANSACTION ISOLATION LEVEL REPEATABLE READ, READ ONLY")
            .execute(&mut *tx)
            .await?;
        let row = sqlx::query!(
            "SELECT f.funder_name, f.funder_kind,
                (SELECT CASE WHEN count(DISTINCT member.company_number) = 1
                    THEN min(member.company_number) END
                 FROM exposed.funder_alias_groups g JOIN exposed.funders member ON member.id = g.funder_id
                 WHERE g.group_id = requested.group_id) AS company_number
             FROM exposed.funder_alias_groups requested
             JOIN exposed.funders f ON f.id = requested.group_id WHERE requested.funder_id = $1",
            id.value()
        )
        .fetch_optional(&mut *tx)
        .await?;
        let Some(row) = row else {
            return Ok(None);
        };
