//! A checked current-database projection of one resolved declaration run.

use bigdecimal::BigDecimal;
use chrono::{DateTime, NaiveDate, Utc};

use super::{
    declaration_ingestion::DeclarationId,
    declaration_resolution::{AttributionBasis, AttributionIssue, UnavailableReason},
    entity_ingestion::{EntityIngestionError, IngestionKey},
    parliament_member::MemberId,
};

/// All rows needed to publish one resolved run in the application database.
pub struct DeclarationLoad {
    pub(crate) ingestion_key: IngestionKey,
    pub(crate) fingerprint: String,
    pub(crate) declarations: Vec<LoadDeclaration>,
    pub(crate) funders: Vec<LoadFunder>,
    pub(crate) funding_entries: Vec<LoadFundingEntry>,
}

/// One source declaration and its existing member identity.
pub struct LoadDeclaration {
    pub(crate) source_declaration_id: DeclarationId,
    pub(crate) member_id: MemberId,
    pub(crate) category_id: u32,
    pub(crate) category_name: String,
    pub(crate) register_id: u32,
    pub(crate) register_published_date: NaiveDate,
    pub(crate) parent_declaration_id: Option<DeclarationId>,
    pub(crate) fetched_at: DateTime<Utc>,
    pub(crate) registration_date: Option<NaiveDate>,
}

/// One resolved identity referenced by an attributed funding occurrence.
pub struct LoadFunder {
    pub(crate) identity_id: String,
    pub(crate) name: String,
    pub(crate) aliases: Vec<String>,
    pub(crate) kind: Option<String>,
    pub(crate) company_number: Option<String>,
}

/// One source funding occurrence and its independent attribution decision.
pub struct LoadFundingEntry {
    pub(crate) source_id: String,
    pub(crate) source_declaration_id: DeclarationId,
    pub(crate) identity_id: Option<String>,
    pub(crate) selected_observation_id: Option<String>,
    pub(crate) attribution_basis: Option<AttributionBasis>,
    pub(crate) selected_parent_declaration_id: Option<DeclarationId>,
    pub(crate) unavailable_reason: Option<UnavailableReason>,
    pub(crate) issues: Vec<AttributionIssue>,
    pub(crate) amount: Option<BigDecimal>,
    pub(crate) currency: Option<String>,
    pub(crate) payment_type: Option<String>,
}

/// Counts committed by a declaration load.
#[derive(Clone, Debug)]
pub struct DeclarationLoadSummary {
    /// Whether this call imported the run or confirmed an exact retry.
    pub outcome: DeclarationLoadOutcome,
    /// Declarations in the run.
    pub declarations: usize,
    /// Distinct resolved identities referenced by selected attributions.
    pub funders: usize,
    /// Original funding occurrences, including unavailable attributions.
    pub funding_entries: usize,
}

/// Result of the atomic load operation.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DeclarationLoadOutcome {
    /// This call committed the run.
    Imported,
    /// This run was already committed from identical artifacts.
    AlreadyLoaded,
}

impl DeclarationLoad {
    /// Constructs a run after its source records and cross-file references are checked.
    ///
    /// # Errors
    /// Rejects empty keys, duplicate IDs, invalid positive IDs, missing references, and
    /// incomplete declaration coverage.
    pub fn checked(
        ingestion_key: IngestionKey,
        fingerprint: String,
        declarations: Vec<LoadDeclaration>,
        funders: Vec<LoadFunder>,
        funding_entries: Vec<LoadFundingEntry>,
    ) -> Result<Self, EntityIngestionError> {
        if ingestion_key.uuid().is_nil() || fingerprint.is_empty() {
            return Err(invalid("declaration load fingerprint is empty"));
        }
        let declaration_ids = declarations
            .iter()
            .map(|row| row.source_declaration_id)
            .collect::<std::collections::BTreeSet<_>>();
        if declaration_ids.len() != declarations.len()
            || declarations.iter().any(|row| {
                row.category_id == 0 || row.category_name.trim().is_empty() || row.register_id == 0
            })
        {
            return Err(invalid("invalid or duplicate declaration load row"));
        }
        let funder_ids = funders
            .iter()
            .map(|row| row.identity_id.as_str())
            .collect::<std::collections::BTreeSet<_>>();
        if funder_ids.len() != funders.len()
            || funders.iter().any(|row| {
                row.identity_id.is_empty()
                    || (row.name.trim().is_empty()
                        && row.company_number.as_deref().is_none_or(str::is_empty))
                    || row.aliases.iter().any(|alias| alias.trim().is_empty())
            })
        {
            return Err(invalid("invalid or duplicate resolved identity"));
        }
        let mut occurrence_ids = std::collections::BTreeSet::new();
        for row in &funding_entries {
            let selected = row.selected_observation_id.is_some();
            if row.source_id.is_empty()
                || row
                    .selected_observation_id
                    .as_deref()
                    .is_some_and(str::is_empty)
                || !occurrence_ids.insert(row.source_id.as_str())
                || !declaration_ids.contains(&row.source_declaration_id)
                || row
                    .identity_id
                    .as_deref()
                    .is_some_and(|id| !funder_ids.contains(id))
                || (row.identity_id.is_some() != row.selected_observation_id.is_some())
                || row.attribution_basis.is_some() != selected
                || row.unavailable_reason.is_some() != !selected
                || row.selected_parent_declaration_id.is_some()
                    != match row.attribution_basis {
                        Some(AttributionBasis::ParentPayer) => true,
                        Some(
                            AttributionBasis::ExplicitUltimatePayer
                            | AttributionBasis::Donor
                            | AttributionBasis::Payer,
                        )
                        | None => false,
                    }
            {
                return Err(invalid(
                    "incoherent funding attribution in declaration load",
                ));
            }
        }
        Ok(Self {
            ingestion_key,
            fingerprint,
            declarations,
            funders,
            funding_entries,
        })
    }

    /// Row counts for the committed run.
    #[must_use]
    pub fn summary(&self) -> DeclarationLoadSummary {
        DeclarationLoadSummary {
            outcome: DeclarationLoadOutcome::Imported,
            declarations: self.declarations.len(),
            funders: self.funders.len(),
            funding_entries: self.funding_entries.len(),
        }
    }
}

fn invalid(message: &str) -> EntityIngestionError {
    EntityIngestionError::DataError(message.to_owned())
}
//! Concrete implementation of the repository

use std::str::FromStr;

use crate::{
    domain::{
        models::{
            entity_search::{
                EntitySearchRequest, FunderSearchMatch, FunderSearchResults, PhoneticRank,
                SearchMatchSource,
            },
            funder::{Funder, FunderId, FunderKind},
            search_similarity::SearchSimilarity,
        },
        repositories::funder_repository::{FunderRepo, FunderRepoError},
    },
    outbound::postgres::{ExposedDatabase, word_similarity_candidate_threshold},
};

impl FunderRepo for ExposedDatabase {
    async fn get_funders_by_text_search_score(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<FunderSearchResults, FunderRepoError> {
        let mut tx = self
            .pool()
            .begin()
            .await
            .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        sqlx::query!(
            "SELECT set_config('pg_trgm.word_similarity_threshold', $1, true)",
            word_similarity_candidate_threshold(req.strictness())
        )
        .fetch_one(&mut *tx)
        .await
        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        let rows = sqlx::query!(
            "
            WITH candidates AS (
                SELECT id FROM exposed.funders WHERE funder_name %> $1
                UNION
                SELECT funder_id FROM exposed.funder_aliases WHERE funder_alias %> $1
            ), scored AS (
                SELECT f.id, f.funder_name AS name, f.funder_kind AS kind,
                    word_similarity($1, f.funder_name) AS canonical_score,
                    a.funder_alias, a.alias_score
                FROM candidates c
                JOIN exposed.funders f ON f.id = c.id
                LEFT JOIN LATERAL (
                    SELECT funder_alias, word_similarity($1, funder_alias) AS alias_score
                    FROM exposed.funder_aliases WHERE funder_id = f.id
                    ORDER BY alias_score DESC, funder_alias COLLATE \"C\" ASC
                    LIMIT 1
                ) a ON true
            ), qualified AS (
                SELECT id, name, kind,
                    CASE WHEN alias_score > canonical_score THEN funder_alias END AS matched_alias,
                    GREATEST(canonical_score, COALESCE(alias_score, 0)) AS similarity_score
                FROM scored
                WHERE GREATEST(canonical_score, COALESCE(alias_score, 0)) >= $2
            ), grouped AS (
                SELECT DISTINCT ON (g.group_id) g.group_id AS id,
                    representative.funder_name AS name, representative.funder_kind AS kind,
                    CASE WHEN q.id <> g.group_id THEN COALESCE(q.matched_alias, q.name)
                        ELSE q.matched_alias END AS matched_alias, q.similarity_score
                FROM qualified q JOIN exposed.funder_alias_groups g ON g.funder_id = q.id
                JOIN exposed.funders representative ON representative.id = g.group_id
                ORDER BY g.group_id, q.similarity_score DESC, q.id
            )
            SELECT id AS \"id!\", name, kind, matched_alias, similarity_score, EXISTS(SELECT FROM qualified WHERE kind = $4) AS \"has_individual!\"
            FROM grouped
            ORDER BY similarity_score DESC, id
            LIMIT $3
            ",
            req.term(),
            req.strictness(),
            i64::from(req.max_entries()),
            FunderKind::Individual.as_ref(),
        )
        .fetch_all(&mut *tx)
        .await
        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        tx.commit()
            .await
            .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        let has_qualifying_individual = rows.first().is_some_and(|row| row.has_individual);
        let matches = rows
            .into_iter()
            .map(|r| {
                let kind = r.kind.map_or(FunderKind::NotSpecified, |ref kind| {
                    FunderKind::from_str(kind).unwrap()
                });
                let funder = Funder::new(FunderId::new(r.id), r.name, kind);
                let score = SearchSimilarity::from(r.similarity_score.unwrap_or(0_f32));
                Ok((
                    FunderSearchMatch::new(
                        funder,
                        r.matched_alias.map_or(SearchMatchSource::Name, |name| {
                            SearchMatchSource::Alias { name }
                        }),
                    ),
                    score,
                ))
            })
            .collect::<Result<Vec<_>, FunderRepoError>>()?;
        Ok(FunderSearchResults {
            matches,
            has_qualifying_individual,
        })
    }
    async fn get_funders_by_phonetic_search(
        &self,
        req: &EntitySearchRequest,
    ) -> Result<Vec<(FunderSearchMatch, PhoneticRank)>, FunderRepoError> {
        let rows = sqlx::query!(r#"
            WITH names AS (
                SELECT id, funder_name AS candidate, NULL::text AS alias
                FROM exposed.funders
                WHERE funder_kind = $2 AND exposed.person_name_codes(funder_name) @> exposed.person_name_codes($1)
                UNION ALL
                SELECT f.id, a.funder_alias, a.funder_alias
                FROM exposed.funder_aliases a JOIN exposed.funders f ON f.id = a.funder_id
                WHERE f.funder_kind = $2 AND exposed.person_name_codes(a.funder_alias) @> exposed.person_name_codes($1)
            ), scored AS (
                SELECT names.*, correction.distance,
                       word_similarity(correction.corrected_query, candidate) AS similarity_score
                FROM names
                CROSS JOIN LATERAL (
                    SELECT string_agg(best.word, ' ' ORDER BY q.position) AS corrected_query,
                           sum(best.distance)::integer AS distance
                    FROM unnest(exposed.person_name_words($1)) WITH ORDINALITY AS q(word, position)
                    LEFT JOIN LATERAL (
                        SELECT cw.word, CASE
                            WHEN char_length(q.word) <= 255 AND char_length(cw.word) <= 255
                            THEN exposed.levenshtein_less_equal(q.word, cw.word, 1)
                            ELSE 2
                        END AS distance
                        FROM unnest(exposed.person_name_words(candidate)) AS cw(word)
                        WHERE exposed.soundex(cw.word) = exposed.soundex(q.word)
                        ORDER BY distance, cw.word COLLATE "C"
                        LIMIT 1
                    ) best ON best.distance <= 1
                    HAVING count(best.word) = count(*) AND count(*) > 0
                ) correction
            ), winners AS (
                SELECT DISTINCT ON (g.group_id) g.group_id AS id,
                    CASE WHEN s.id <> g.group_id THEN COALESCE(s.alias, s.candidate)
                        ELSE s.alias END AS alias, s.distance, s.similarity_score
                FROM scored s JOIN exposed.funder_alias_groups g ON g.funder_id = s.id
                WHERE s.similarity_score >= $4
                ORDER BY g.group_id, s.distance, s.similarity_score DESC, s.id,
                    s.alias IS NOT NULL, s.alias COLLATE "C"
            )
            SELECT f.id, f.funder_name AS name, f.funder_kind AS kind, w.alias, w.distance AS "distance!",
                   w.similarity_score AS "similarity_score!"
            FROM winners w JOIN exposed.funders f ON f.id = w.id
            ORDER BY w.distance, w.similarity_score DESC, f.id
            LIMIT $3
        "#, req.term(), FunderKind::Individual.as_ref(), i64::from(req.max_entries()), req.strictness())
        .fetch_all(self.pool()).await.map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?;
        rows.into_iter()
            .map(|row| {
                let rank = PhoneticRank::new(
                    u32::try_from(row.distance)
                        .map_err(|e| FunderRepoError::DatabaseError(e.to_string()))?,
                    SearchSimilarity::from(row.similarity_score),
                );
                Ok((
                    FunderSearchMatch::new(
                        Funder::new(
                            FunderId::new(row.id),
                            row.name,
                            row.kind
                                .as_deref()
                                .map_or(Ok(FunderKind::NotSpecified), FunderKind::from_str)
                                .map_err(|error| {
                                    FunderRepoError::DatabaseError(error.to_string())
                                })?,
                        ),
                        row.alias.map_or(SearchMatchSource::Name, |name| {
                            SearchMatchSource::Alias { name }
                        }),
                    ),
                    rank,
                ))
            })
            .collect()
    }
}

