    SELECT DISTINCT left_funder_id AS source, right_funder_id AS target
    FROM links
    UNION
    SELECT right_funder_id, left_funder_id FROM links
), reachable AS (
    SELECT DISTINCT source AS funder_id, source AS member_id FROM edges
    UNION
    SELECT r.funder_id, e.target FROM reachable r JOIN edges e ON e.source = r.member_id
)
SELECT funder_id, min(member_id::text)::uuid AS group_id
FROM reachable GROUP BY funder_id
UNION ALL
SELECT id, id FROM exposed.funders f
WHERE NOT EXISTS (SELECT FROM edges WHERE source = f.id);

